<script setup lang="ts">import{computed,ref,onMounted}from'vue';import{learningApi}from'@/api/learning';import{useAuthStore}from'@/stores/auth';const auth=useAuthStore();const apiMode=computed(()=>location.origin);const modelStatus=ref('正在检查模型配置…');onMounted(async()=>{try{modelStatus.value=(await learningApi.assistantStatus()).message}catch{modelStatus.value='模型状态获取失败，请到智能答疑页面重试'}})</script>
<template><div><header class="page-head"><div><p class="eyebrow">SETTINGS</p><h1>设置</h1><p>账号信息与系统能力概览。</p></div></header><div class="grid two-col"><section class="card"><h2>账号</h2><div class="field"><label>当前角色</label><strong>{{ !auth.user ? '正在读取身份…' : auth.user.role==='admin' ? '管理员' : '普通用户' }}</strong><p class="reason">{{auth.user?.role==='admin' ? '可维护公共知识库、公共课程与知识点目录，也可使用个人学习功能。' : '可学习公共课程、答疑和测评，只能查看公共知识库，不能上传、修改或删除公共资源。'}}</p><p v-if="auth.user && auth.user.role!=='admin'" class="notice">注册账号默认为普通用户。首个管理员由部署者使用独立初始化令牌设置，无法在个人设置中自行提权。</p></div><div class="field"><label>用户名</label><input :value="auth.user?.username" disabled/></div><div class="field"><label>邮箱</label><input :value="auth.user?.email" disabled/></div></section><section class="card"><h2>运行模式</h2><div class="list"><div class="list-item"><div class="grow"><b>API 地址</b><div class="reason">{{apiMode}}/api/v1</div></div><span class="pill">独立服务</span></div><div class="list-item"><div class="grow"><b>Embedding / LLM</b><div class="reason">由后端环境变量管理，API Key 不会发送到浏览器。</div></div></div><div class="list-item"><div class="grow"><b>模型可用状态</b><div class="reason">{{modelStatus}}</div></div></div></div></section></div></div></template>

